import{_ as a,c as i,o as s,a3 as l}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/troubleshooting.md","filePath":"fr/guide/troubleshooting.md","lastUpdated":1787284674000}'),n={name:"fr/guide/troubleshooting.md"};function t(r,e,o,p,u,c){return s(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h1><p>Cette page recense les problèmes courants rencontrés avec ClipboxAI sur macOS et leur résolution.</p><h2 id="l-application-ne-demarre-pas-ou-plante-au-lancement" tabindex="-1">L&#39;application ne démarre pas ou plante au lancement <a class="header-anchor" href="#l-application-ne-demarre-pas-ou-plante-au-lancement" aria-label="Permalink to &quot;L&#39;application ne démarre pas ou plante au lancement&quot;">​</a></h2><ol><li>Assurez-vous que votre version de macOS répond au minimum requis (macOS 14 Sonoma+).</li><li>Quittez et relancez l&#39;application.</li><li>Redémarrez votre Mac.</li><li><s>Si téléchargé depuis GitHub Releases, essayez la dernière version ou la version notariée.</s></li><li>Si les problèmes persistent, collectez les journaux (ci-dessous) et ouvrez un ticket.</li></ol><h2 id="l-historique-du-presse-papiers-ne-capture-pas-les-copies" tabindex="-1">L&#39;historique du presse-papiers ne capture pas les copies <a class="header-anchor" href="#l-historique-du-presse-papiers-ne-capture-pas-les-copies" aria-label="Permalink to &quot;L&#39;historique du presse-papiers ne capture pas les copies&quot;">​</a></h2><p>Symptômes : les nouvelles copies n&#39;apparaissent pas dans le panneau d&#39;historique.</p><p>Liste de contrôle :</p><ol><li>Assurez-vous que l&#39;application est en cours d&#39;exécution et que son icône de barre de menus est visible.</li><li>Confirmez que <strong>la surveillance du presse-papiers</strong> est activée dans <strong>Réglages → Confidentialité / Général</strong>.</li><li>L&#39;application a besoin de la permission macOS appropriée pour lire le presse-papiers en arrière-plan — voir <a href="/fr/guide/permissions.html">Permissions</a>.</li><li>Certaines applications (gestionnaires de mots de passe, champs de saisie sécurisés) bloquent intentionnellement l&#39;accès au presse-papiers ; c&#39;est normal.</li></ol><h2 id="les-actions-ia-cloud-ne-renvoient-pas-de-resultat" tabindex="-1">Les actions IA cloud ne renvoient pas de résultat <a class="header-anchor" href="#les-actions-ia-cloud-ne-renvoient-pas-de-resultat" aria-label="Permalink to &quot;Les actions IA cloud ne renvoient pas de résultat&quot;">​</a></h2><p>Symptômes : une action IA échoue, bloque ou affiche une erreur de configuration.</p><p>Liste de contrôle :</p><ol><li>Ouvrez <strong>Réglages → IA</strong> et confirmez qu&#39;un fournisseur est sélectionné et qu&#39;une clé est saisie.</li><li>Vérifiez que la clé est valide pour ce fournisseur et dispose de quota/crédits.</li><li>Vérifiez votre connexion réseau — l&#39;IA cloud nécessite un accès à Internet.</li><li>Confirmez que le nom du modèle sélectionné est correct pour le fournisseur.</li><li>Si la bannière de configuration apparaît encore dans la fenêtre Outil IA, la clé n&#39;est pas enregistrée dans le Keychain ; saisissez-la à nouveau.</li></ol><h2 id="l-installation-depuis-le-marketplace-n-ajoute-pas-l-action" tabindex="-1">L&#39;installation depuis le Marketplace n&#39;ajoute pas l&#39;action <a class="header-anchor" href="#l-installation-depuis-le-marketplace-n-ajoute-pas-l-action" aria-label="Permalink to &quot;L&#39;installation depuis le Marketplace n&#39;ajoute pas l&#39;action&quot;">​</a></h2><p>Symptômes : cliquer sur <strong>Installer</strong> ne fait rien, ou l&#39;application ne s&#39;ouvre pas.</p><p>Liste de contrôle :</p><ol><li>Le lien profond <code>clipboxai://install?action=&lt;id&gt;</code> doit être géré par l&#39;application installée — assurez-vous que ClipboxAI est installé et en cours d&#39;exécution.</li><li>Si votre navigateur bloque le lien profond, copiez-le et ouvrez-le manuellement, ou installez depuis l&#39;onglet <strong>Marketplace</strong> de l&#39;application.</li><li>Vérifiez que l&#39;ID de l&#39;action est toujours publié dans le marketplace.</li></ol><h2 id="reinitialiser-l-application" tabindex="-1">Réinitialiser l&#39;application <a class="header-anchor" href="#reinitialiser-l-application" aria-label="Permalink to &quot;Réinitialiser l&#39;application&quot;">​</a></h2><p>Pour réinitialiser les réglages et effacer les données locales :</p><ol><li>Quittez ClipboxAI.</li><li>Supprimez le conteneur (cela supprime l&#39;historique et les réglages) :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>Rouvrez l&#39;application et reconfigurez-la. Les clés API du Keychain doivent être supprimées séparément dans <strong>Keychain Access</strong> si vous le souhaitez.</li></ol><h2 id="comment-collecter-les-journaux-de-debogage" tabindex="-1">Comment collecter les journaux de débogage <a class="header-anchor" href="#comment-collecter-les-journaux-de-debogage" aria-label="Permalink to &quot;Comment collecter les journaux de débogage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copier les journaux sur le Bureau pour les partager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/Clipboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>Ouvrez ensuite un ticket sur <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub</a> et joignez les journaux.</p><h2 id="signaler-un-probleme" tabindex="-1">Signaler un problème <a class="header-anchor" href="#signaler-un-probleme" aria-label="Permalink to &quot;Signaler un problème&quot;">​</a></h2><p>Lors de l&#39;ouverture d&#39;un ticket, indiquez :</p><ul><li>La version de macOS (menu Pomme → À propos de ce Mac)</li><li>La version de ClipboxAI (menu de l&#39;application → À propos)</li><li>Les étapes pour reproduire</li><li>Les journaux (voir ci-dessus)</li></ul><p>Cela aide les mainteneurs à identifier et corriger le problème plus rapidement.</p>`,28)])])}const m=a(n,[["render",t]]);export{h as __pageData,m as default};
